adcs_vec3_t rate_vec;
double norm;
double scale;
int valid;

/* 每次调用都初始化输出，保证所有字段被赋值 */
gr_output.mode = GR_NOMINAL;
gr_output.clean = 0U;
gr_output.norm_rad_s = 0.0;
gr_output.energy_rad2_s2 = 0.0;
gr_output.capped_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};

valid = 1;

if (gr_input.enable == 0) {
    /* Disabled：NOMINAL，clean清零，清零向量输出 */
    gr_state.mode = GR_NOMINAL;
    gr_state.clean = 0U;
    gr_output.mode = GR_NOMINAL;
    gr_output.clean = 0U;
    gr_output.norm_rad_s = 0.0;
    gr_output.energy_rad2_s2 = 0.0;
    gr_output.capped_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

if (gr_input.rate_rad_s == NULL) {
    valid = 0;
} else if (!adcs_is_finite_vec3(gr_input.rate_rad_s)) {
    valid = 0;
} else if ((!isfinite(gr_config.recovered_rad_s)) ||
           (!isfinite(gr_config.saturated_rad_s)) ||
           (gr_config.recovered_rad_s < 0.0) ||
           (gr_config.recovered_rad_s >= gr_config.saturated_rad_s) ||
           (gr_config.required_clean < 1U) ||
           (gr_config.required_clean > 20U)) {
    valid = 0;
}

if (!valid) {
    /* latch FAULT until disable */
    gr_state.mode = GR_FAULT;
    gr_state.clean = 0U;
    gr_output.mode = GR_FAULT;
    gr_output.clean = 0U;
    gr_output.norm_rad_s = 0.0;
    gr_output.energy_rad2_s2 = 0.0;
    gr_output.capped_rate_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

rate_vec = *gr_input.rate_rad_s;
norm = adcs_vec3_norm(&rate_vec);
gr_output.norm_rad_s = norm;
gr_output.energy_rad2_s2 = adcs_vec3_dot(&rate_vec, &rate_vec);

if (norm > gr_config.saturated_rad_s) {
    scale = gr_config.saturated_rad_s / norm;
    gr_output.capped_rate_rad_s = adcs_vec3_scale(&rate_vec, scale);
} else {
    gr_output.capped_rate_rad_s = rate_vec;
}

/* 规范表状态机 */
if (norm >= gr_config.saturated_rad_s) {
    /* 任意状态下饱和 */
    gr_state.mode = GR_SATURATED;
    gr_state.clean = 0U;
} else if (norm <= gr_config.recovered_rad_s) {
    if ((gr_state.mode == GR_SATURATED) || (gr_state.mode == GR_RECOVERING)) {
        gr_state.mode = GR_RECOVERING;
        gr_state.clean += 1U;
        if (gr_state.clean >= gr_config.required_clean) {
            gr_state.mode = GR_NOMINAL;
        }
    }
    /* 其它状态（NOMINAL/FAULT）不改变 */
} else {
    /* recovered < norm < saturated */
    if ((gr_state.mode == GR_SATURATED) || (gr_state.mode == GR_RECOVERING)) {
        gr_state.mode = GR_SATURATED;
        gr_state.clean = 0U;
    }
    /* NOMINAL 保持 NOMINAL，clean 不变 */
}

gr_output.mode = gr_state.mode;
gr_output.clean = gr_state.clean;

